package ug.audiocity.studio;
import android.media.*;import java.util.*;
/** A live monitor; when backing playback runs, the main engine mixes these voices instead. */
public final class LiveMidi {
 public final SynthPoly voices;final AudioIO.Engine backing;volatile boolean running;volatile double master=.85;volatile String error;Thread thread;volatile AudioTrack device;
 public LiveMidi(AudioIO.Engine engine,Synth.Config config){backing=engine;voices=new SynthPoly(config);}
 public synchronized void start(){if(running)return;if(thread!=null&&thread.isAlive()){error="MIDI audio is still stopping. Reconnect after a moment.";return;}running=true;backing.midiMonitor=voices;thread=new Thread(()->{AudioTrack output=null;try{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_AUDIO);int min=AudioTrack.getMinBufferSize(Core.RATE,AudioFormat.CHANNEL_OUT_STEREO,AudioFormat.ENCODING_PCM_FLOAT);output=new AudioTrack.Builder().setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(Core.RATE).setChannelMask(AudioFormat.CHANNEL_OUT_STEREO).setEncoding(AudioFormat.ENCODING_PCM_FLOAT).build()).setTransferMode(AudioTrack.MODE_STREAM).setBufferSizeInBytes(Math.max(min,4096)).setPerformanceMode(AudioTrack.PERFORMANCE_MODE_LOW_LATENCY).build();device=output;output.play();float[] samples=new float[1024];while(running){if(backing.playing)Arrays.fill(samples,0);else{voices.render(samples,512);float left=0,right=0;for(int i=0;i<samples.length;i++){samples[i]=(float)Math.max(-.89125,Math.min(.89125,samples[i]*master));if(i%2==0)left=Math.max(left,Math.abs(samples[i]));else right=Math.max(right,Math.abs(samples[i]));}backing.peakLeft=left;backing.peakRight=right;backing.peak=Math.max(left,right);backing.peakHold=Math.max(backing.peakHold,backing.peak);}int written=0;while(running&&written<samples.length){int n=output.write(samples,written,samples.length-written,AudioTrack.WRITE_BLOCKING);if(n<=0){if(!running)break;throw new java.io.IOException("MIDI monitor audio error "+n);}written+=n;}}}catch(Exception e){error=e.getMessage();}finally{running=false;backing.midiMonitor=null;if(output!=null){try{output.pause();output.flush();output.release();}catch(Exception ignored){}}device=null;}},"CityStudio-MIDI-monitor");thread.start();}
 public synchronized void stop(){running=false;backing.midiMonitor=null;voices.silence();if(device!=null)try{device.pause();}catch(Exception ignored){}if(thread!=null)try{thread.join(1200);}catch(InterruptedException e){Thread.currentThread().interrupt();}if(thread==null||!thread.isAlive())thread=null;}
}
